    n=int(d[0]); m=int(d[1]); X=int(d[2])
    adj=[[] for _ in range(2*n)]
    for i in range(m):
        u=int(d[3+2*i])-1; v=int(d[4+2*i])-1
        adj[u].append(v)          # state 0: u->v
        adj[n+v].append(n+u)      # state 1: reversed v->u
    for x in range(n):
        adj[x].append(n+x); adj[n+x].append(x)
    INF=float('inf')
    dist=[INF]*(2*n)
    dist[0]=0
    pq=[(0,0)]
    while pq:
        dd,s=heapq.heappop(pq)
        if dd>dist[s]: continue
        if s<n:
            if s==n-1:
                print(dd); return
        ws = X if (s<n and False) else 0
        # cost: edges cost 1 except flip edges cost X
        for t in adj[s]:
            if (t>=n) != (s>=n):
                if t==s+n or t==s-n:
                    if abs(t-s)==n:
                        nd=dd+X
                    else:
                        nd=dd+1
                else:
                    nd=dd+1
            else:
                nd=dd+1
            if nd<dist[t]:
                dist[t]=nd; heapq.heappush(pq,(nd,t))
    print(min(dist[n-1],dist[2*n-1]))
