import sys
import numpy as np
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); A=[int(x) for x in data[1:n]]
    M=998244353
    primes={}
    for a in A:
        x=a; d=2
        while d*d<=x:
            if x%d==0:
                while x%d==0:
                    x//=d
                primes.setdefault(d,True)
            d+=1
        if x>1: primes.setdefault(x,True)
    ans=1
    for p in primes:
        es=[]
        for a in A:
            c=0; x=a
            while x%p==0:
                x//=p; c+=1
            es.append(c)
        R=sum(es)
        pw=np.ones(R+1,dtype=np.int64)
        for v in range(1,R+1):
            pw[v]=pw[v-1]*p%M
        g0=pw.copy(); g0[0]=0
        g1=np.zeros(R+1,dtype=np.int64); g1[0]=1
        for e in es:
            if e==0:
                n0=g0.copy(); n1=g1.copy()
            else:
                n0=np.zeros(R+1,dtype=np.int64); n1=np.zeros(R+1,dtype=np.int64)
                if e<=R:
                    n0[e:]+=g0[:R+1-e]
                    n1[e:]+=g1[:R+1-e]
                    n0[:R+1-e]+=g0[e:]
                    n1[:R+1-e]+=g1[e:]
                n0%=M; n1%=M
            n0=n0*pw%M
            n1=n1*pw%M
            n1[0]=(n1[0]+n0[0])%M
            n0[0]=0
            g0,g1=n0,n1
        ans=ans*(int(g1.sum())%M)%M
    print(ans%M)
main()

