import sys
import numpy as np
def main():
    data=sys.stdin.buffer.read().split()
    p=0
    N=int(data[p]); M=int(data[p+1]); Q=int(data[p+2]); p+=3
    E=[]
    for _ in range(M):
        a=int(data[p])-1; b=int(data[p+1])-1; c=int(data[p+2]); p+=3
        E.append((a,b,c))
    qs=[]
    closed=set()
    for _ in range(Q):
        t=int(data[p])
        if t==1:
            i=int(data[p+1])-1; p+=2
            qs.append((1,i)); closed.add(i)
        else:
            x=int(data[p+1])-1; y=int(data[p+2])-1; p+=3
            qs.append((2,x,y))
    INF=10**18
    D=np.full((N,N),INF,dtype=np.int64)
    np.fill_diagonal(D,0)
    for i,(a,b,c) in enumerate(E):
        if i not in closed:
            if c<D[a,b]:
                D[a,b]=c; D[b,a]=c
    for k in range(N):
        D=np.minimum(D,D[:,k:k+1]+D[k:k+1,:])
    ans=[]
    for q in reversed(qs):
        if q[0]==1:
            a,b,c=E[q[1]]
            D=np.minimum(D,np.minimum(D[:,a:a+1]+c+D[b:b+1,:],D[:,b:b+1]+c+D[a:a+1,:]))
        else:
            v=int(D[q[1],q[2]])
            ans.append(-1 if v>=INF else v)
    ans.reverse()
    sys.stdout.write("\n".join(map(str,ans))+("\n" if ans else ""))
main()

