import sys
from math import factorial
def main():
    A,B,M=map(int,sys.stdin.read().split())
    N=A*B-1
    lam=[A]*(B-1)+[A-1]
    conj=[sum(1 for l in lam if l>j) for j in range(lam[0])]
    prod=1
    for i,l in enumerate(lam):
        for j in range(l):
            prod*=(l-j-1)+(conj[j]-i-1)+1
    fl=factorial(N)//prod
    rows=[[] for _ in range(B)]
    cnt=[0]
    def check():
        for n in range(0,N+1):
            c1=sum(1 for v in rows[0] if v<=n)
            if c1>A-1: continue
            word=[]
            for r in range(B-1,-1,-1):
                word+=[v for v in rows[r] if v>n]
            P=[]
            for x in word:
                i=0
                while True:
                    if i==len(P):
                        P.append([x]);break
                    row=P[i]
                    j=None
                    for k,y in enumerate(row):
                        if y>x:
                            j=k;break
                    if j is None:
                        row.append(x);break
                    row[j],x=x,row[j]
                    i+=1
            if len(P)<=B-1: return True
        return False
    def gen(v):
        if v>N:
            if check(): cnt[0]+=1
            return
        for r in range(B):
            if len(rows[r])<lam[r] and (r==0 or len(rows[r-1])>len(rows[r])):
                rows[r].append(v)
                gen(v+1)
                rows[r].pop()
    gen(1)
    print(cnt[0]*fl%M)
main()

