import sys, heapq
def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0]); pos = 1
    out = []
    for _ in range(t):
        n = int(data[pos]); m = int(data[pos+1]); pos += 2
        b = []
        for i in range(n):
            b.append((int(data[pos]), int(data[pos+1]))); pos += 2
        b.sort()
        pref = [0]*(n+1)
        for i in range(n):
            v, p = b[i]
            g = v - p
            pref[i+1] = pref[i] + (g if g > 0 else 0)
        need = m - 1
        best = 0
        if need == 0:
            best = pref[n]
        else:
            heap = []
            sp = 0
            for k in range(n, -1, -1):
                if k < n:
                    p = b[k][1]
                    if len(heap) < need:
                        heapq.heappush(heap, -p); sp += p
                    elif p < -heap[0]:
                        top = -heapq.heappushpop(heap, -p)
                        sp += p - top
                if len(heap) == need:
                    cand = pref[k] + need - sp
                    if cand > best:
                        best = cand
        out.append(str(best))
    sys.stdout.write("\n".join(out) + "\n")
main()

