from functools import lru_cache
def solve(M, boxes):
    n=len(boxes)
    NEG=float('-inf')
    @lru_cache(None)
    def F(O, U):  # O: sorted tuple of open box indices (size M), U: frozenset unbought (bitmask)
        # Ball fills min V in O
        m=min(O,key=lambda i:boxes[i][0])
        Op=tuple(i for i in O if i!=m)
        return (boxes[m][0]-1)+D(Op,U)
    @lru_cache(None)
    def D(Op,U):
        best=0
        for x in range(n):
            if U>>x&1:
                v=(1-boxes[x][1])+F(tuple(sorted(Op+(x,))),U&~(1<<x))
                best=max(best,v)
        return best
    ans=0
    from itertools import combinations
    full=(1<<n)-1
    for S in combinations(range(n),M):
        if any(boxes[i][0]==1 for i in S): pass
        base=sum(1-boxes[i][1] for i in S)
        U=full
        for i in S: U&=~(1<<i)
        ans=max(ans,base+F(tuple(S),U))
    return ans
