def brute(M, boxes):
    n=len(boxes)
    @lru_cache(None)
    def F(O, U):
        m=min(O,key=lambda i:boxes[i][0])
        Op=tuple(i for i in O if i!=m)
        return (boxes[m][0]-1)+D(Op,U)
    @lru_cache(None)
    def D(Op,U):
        best=0
        for x in range(n):
            if U>>x&1:
                best=max(best,(1-boxes[x][1])+F(tuple(sorted(Op+(x,))),U&~(1<<x)))
        return best
    ans=0
    full=(1<<n)-1
    for S in combinations(range(n),M):
        base=sum(1-boxes[i][1] for i in S)
        U=full
        for i in S: U&=~(1<<i)
        ans=max(ans,base+F(tuple(S),U))
    return ans
def fast(M, boxes):
    b=sorted(boxes)
    n=len(b)
    if M==1:
        return sum(max(0,v-p) for v,p in b)
    best=0
    pref=0
    for k in range(n+1):
        # prefix 0..k-1 as X
        if k>0: pref+=max(0,b[k-1][0]-b[k-1][1])
        suf=sorted(p for v,p in b[k:])
        if len(suf)>=M-1:
            s=sum(1-p for p in suf[:M-1])
            best=max(best,pref+s)
    return best
