class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = 805
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        def popc(x):
            return bin(x).count('1')

        # reach[c]: minimal ops to reach 1 from c
        reach = [10**9] * (N + 1)
        reach[1] = 0
        for c in range(2, N + 1):
            reach[c] = 1 + reach[popc(c)]

        ok = [c for c in range(1, N + 1) if reach[c] <= k - 1]

        total = 0
        for c in ok:
            ones = 0
            cnt = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = L - i - 1
                    need = c - ones
                    if 0 <= need <= rem:
                        cnt += C[rem][need]
                    ones += 1
            total = (total + cnt) % MOD
        return total % MOD

