import sys
def main():
    d=sys.stdin.read().split()
    n,m=int(d[0]),int(d[1])
    rows=[0]*n
    for i in range(m):
        u=int(d[2+2*i])-1; v=int(d[3+2*i])-1
        rows[u]|=1<<v; rows[v]|=1<<u
    rank=0; piv=[]
    for c in range(n):
        r=None
        for i in range(rank,n):
            if rows[i]>>c&1:
                r=i;break
        if r is None: continue
        rows[rank],rows[r]=rows[r],rows[rank]
        for i in range(n):
            if i!=rank and rows[i]>>c&1:
                rows[i]^=rows[rank]
        piv.append(c); rank+=1
    ps=set(piv)
    basis=[]
    for f in range(n):
        if f in ps: continue
        vec=1<<f
        for i,p in enumerate(piv):
            if rows[i]>>f&1:
                vec|=1<<p
        basis.append(vec)
    X=[0]*n
    for j,b in enumerate(basis):
        for v in range(n):
            if b>>v&1:
                X[v]|=1<<j
    if any(x==0 for x in X):
        print("No")
    else:
        print("Yes")
        print(*X)
