import sys
from functools import lru_cache
from typing import List
sys.setrecursionlimit(10000)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def G(o, e, q):
            # q: parity of last placed (1 odd, 0 even); o,e remaining counts
            if o + e == 0:
                return 1
            r = 1 - q
            cnt = o if r == 1 else e
            if cnt == 0:
                return 0
            return cnt * G(o - 1, e, 1) if r == 1 else cnt * G(o, e - 1, 0)

        o = (n + 1) // 2
        e = n // 2
        total = 0
        for r in (0, 1):
            cnt = o if r == 1 else e
            if cnt == 0:
                continue
            if r == 1:
                total += cnt * G(o - 1, e, 1)
            else:
                total += cnt * G(o, e - 1, 0)
        if k > total:
            return []

        rem = list(range(1, n + 1))
        res = []
        prev = None
        for _ in range(n):
            cur_o = sum(1 for x in rem if x % 2 == 1)
            cur_e = len(rem) - cur_o
            chosen = False
            for idx, x in enumerate(rem):
                px = x % 2
                if prev is not None and px == prev:
                    continue
                no = cur_o - (1 if px == 1 else 0)
                ne = cur_e - (1 if px == 0 else 0)
                ways = G(no, ne, px)
                if k <= ways:
                    res.append(x)
                    rem.pop(idx)
                    prev = px
                    chosen = True
                    break
                k -= ways
            if not chosen:
                return []
        return res

