class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        w = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k) % k)
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        full = 1 << k
        sh = [[0] * k for _ in range(full)]
        for mask in range(full):
            for s in range(k):
                nm = 0
                for r in range(k):
                    if mask >> r & 1:
                        nm |= 1 << ((r + s) % k)
                sh[mask][s] = nm
        reach = [0] * (half + 1)
        reach[half] = 1
        for i in range(half - 1, -1, -1):
            m = 0
            lo = 1 if i == 0 else 0
            for d in range(lo, 10):
                s = d * w[i] % k
                m |= sh[reach[i + 1]][s]
            reach[i] = m
        if not (reach[0] >> 0 & 1):
            return ""
        digs = []
        cur = 0
        for i in range(half):
            lo = 1 if i == 0 else 0
            chosen = None
            for d in range(9, lo - 1, -1):
                nr = (cur + d * w[i]) % k
                need = (-nr) % k
                if reach[i + 1] >> need & 1:
                    chosen = d
                    cur = nr
                    break
            digs.append(chosen)
        s = ''.join(map(str, digs))
        return s + s[:n // 2][::-1]

