            for d in range(9, lo - 1, -1):
                nr = (cur + d * w[i]) % k
                need = (-nr) % k
                if reach[i + 1] >> need & 1:
                    chosen = d
                    cur = nr
                    break
            digs.append(chosen)
        s = ''.join(map(str, digs))
        return s + s[:n // 2][::-1]

