class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums; n = len(a)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]
        ss = []; vs = []; cs = []; neg = []
        def S(p):
            if p >= n:
                return 0
            j = bisect.bisect_left(neg, -p)
            return cs[j] - vs[j] * (p - ss[j])
        r = n - 1; total = 0
        ng = [n] * n; st = []
        for i in range(n - 1, -1, -1):
            while st and a[st[-1]] <= a[i]:
                st.pop()
            ng[i] = st[-1] if st else n
            st.append(i)
        for l in range(n - 1, -1, -1):
            g = ng[l]
            while ss and ss[-1] < g:
                ss.pop(); vs.pop(); cs.pop(); neg.pop()
            base = cs[-1] if cs else 0
            c = a[l] * (g - l) + base
            ss.append(l); vs.append(a[l]); cs.append(c); neg.append(-l)
            while S(l) - S(r + 1) - (P[r + 1] - P[l]) > k:
                r -= 1
