                for x, c in dp.items():
                    a = cnt[i] + x
                    k = 0 if last else a
                    if nd.get(k, INF) > c + a:
                        nd[k] = c + a
                    if a >= f:
                        k = 0 if last else a - f
                        v = c + a - f
                    else:
                        k = 0
                        v = c + f - a
                    if nd.get(k, INF) > v:
                        nd[k] = v
                dp = nd
                if min(dp.values()) >= best:
                    ok = False
                    break
            if ok:
                r = dp.get(0, INF)
                if r < best:
                    best = r
        return best

