    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1])
    F=[int(x) for x in data[2:2+H*W]]
    p=2+H*W
    Q=int(data[p]); p+=1
    N=H*W
    edges=[]
    for i in range(H):
        for j in range(W):
            u=i*W+j
            if j+1<W:
                v=u+1; edges.append((min(F[u],F[v]),u,v))
            if i+1<H:
                v=u+W; edges.append((min(F[u],F[v]),u,v))
    edges.sort(reverse=True)
    par=list(range(N)); sz=[1]*N
    pw=[-1]*N
    def find(x):
        while par[x]!=x:
            x=par[x]
        return x
    for w,u,v in edges:
        ru=find(u); rv=find(v)
        if ru==rv: continue
        if sz[ru]<sz[rv]: ru,rv=rv,ru
        par[rv]=ru; sz[ru]+=sz[rv]; pw[rv]=w
    out=[]
    for _ in range(Q):
        A,B,Y,C,D,Z=(int(x) for x in data[p:p+6]); p+=6
        s=(A-1)*W+(B-1); t=(C-1)*W+(D-1)
        L=min(F[s],F[t])
