class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = float('inf')
        mn = [INF] * k
        best = -INF
        p = 0
        mn[0] = 0
        for j in range(1, len(nums) + 1):
            p += nums[j - 1]
            r = j % k
            if mn[r] != INF:
                c = p - mn[r]
                if c > best:
                    best = c
            if p < mn[r]:
                mn[r] = p
        return int(best)

