class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0
        masks = [1] * n
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                masks[i] |= masks[i] << v
            ok = True
            for i in range(n):
                if not (masks[i] >> nums[i]) & 1:
                    ok = False
                    break
            if ok:
                return k + 1
        return -1

