from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        def ok(W):
            radj = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= W:
                    radj[b].append(a)
            seen = [False] * n
            seen[0] = True
            dq = deque([0])
            cnt = 1
            while dq:
                u = dq.popleft()
                for v in radj[u]:
                    if not seen[v]:
                        seen[v] = True
                        cnt += 1
                        dq.append(v)
            return cnt == n

        ws = sorted(set(w for _, _, w in edges))
        if not ws or not ok(ws[-1]):
            return -1
        lo, hi = 0, len(ws) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(ws[mid]):
                hi = mid
            else:
                lo = mid + 1
        return ws[lo]

