    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = float('inf')
        pairs = [(x, y) for x in range(3) for y in range(3) if x != y]
        dp = {}
        for x, y in pairs:
            dp[(x, y)] = cost[0][x] + cost[n-1][y]
        for i in range(1, m):
            nd = {}
            for x, y in pairs:
                best = INF
                for (px, py), v in dp.items():
                    if px != x and py != y and v < best:
                        best = v
                nd[(x, y)] = best + cost[i][x] + cost[n-1-i][y]
            dp = nd
        return min(dp.values())

